"""HTTP API for the PNG charts generated by the analytics pipeline.

Run from the project root with:
    uvicorn api:app --host 127.0.0.1 --port 8000
"""
from datetime import datetime, timezone
import os
import secrets
from pathlib import Path

from fastapi import Depends, FastAPI, Header, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse, Response
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
import httpx
from PIL import Image, UnidentifiedImageError
from pydantic import BaseModel

RAIZ = Path(__file__).resolve().parent
CARPETA_GRAFICAS = RAIZ / "data" / "reportes"

TITULOS_GRAFICAS = {
    "empresas_grafica_1.png": "Cantidad de empresas por sector",
    "empresas_grafica_2.png": "Empresas activas vs inactivas",
    "empresas_grafica_3.png": "Empresas activas e inactivas por sector",
    "registros_grafica_1.png": "Participaciones por estado",
    "registros_grafica_2.png": "Participaciones por mes",
    "registros_grafica_3.png": "Los 10 retos con más participantes",
    "retos_grafica_1.png": "Cantidad de retos por estado",
    "retos_grafica_2.png": "Retos que empiezan cada mes",
    "retos_grafica_3.png": "Distribución de la duración de los retos",
}


class Grafica(BaseModel):
    title: str
    image_url: str


class GraficaAnalitica(BaseModel):
    id: str
    title: str
    imageUrl: str
    altText: str
    generatedAt: str


bearer = HTTPBearer(auto_error=False)
URL_VALIDACION_SESION = os.getenv(
    "ANALYTICS_AUTH_VERIFY_URL",
    "http://localhost:8081/api/usuarios/me",
)


async def verificar_token(
    credentials: HTTPAuthorizationCredentials | None = Depends(bearer),
    session_cookie: str | None = Header(default=None, alias="Cookie"),
) -> None:
    if credentials is None and not session_cookie:
        raise HTTPException(
            status_code=401,
            detail="Se requiere iniciar sesión",
            headers={"WWW-Authenticate": "Bearer"},
        )

    headers = {}
    if credentials is not None and credentials.scheme.lower() == "bearer":
        token = credentials.credentials
        token_configurado = os.getenv("ANALYTICS_API_TOKEN")
        if token_configurado and secrets.compare_digest(token, token_configurado):
            return
        headers["Authorization"] = f"Bearer {token}"
    if session_cookie:
        headers["Cookie"] = session_cookie

    try:
        async with httpx.AsyncClient(timeout=5.0) as cliente:
            respuesta = await cliente.get(
                URL_VALIDACION_SESION,
                headers=headers,
            )
    except httpx.RequestError as error:
        raise HTTPException(
            status_code=503,
            detail="No se pudo validar la sesión con el backend principal",
        ) from error

    if respuesta.status_code == 200:
        try:
            usuario = respuesta.json()
        except ValueError as error:
            raise HTTPException(
                status_code=503,
                detail="El backend principal devolvió una respuesta de sesión inválida",
            ) from error
        if not isinstance(usuario, dict):
            raise HTTPException(
                status_code=503,
                detail="El backend principal devolvió una respuesta de sesión inválida",
            )
        if str(usuario.get("rol", "")).upper() != "ADMIN":
            raise HTTPException(
                status_code=403,
                detail="Se requiere el rol ADMIN para consultar analítica",
            )
        return
    if respuesta.status_code in (401, 403):
        raise HTTPException(
            status_code=respuesta.status_code,
            detail="La sesión no está autorizada para consultar analítica",
            headers={"WWW-Authenticate": "Bearer"}
            if respuesta.status_code == 401
            else None,
        )
    raise HTTPException(
        status_code=503,
        detail="El backend principal no pudo validar la sesión",
    )


app = FastAPI(title="API de analítica")
app.add_middleware(
    CORSMiddleware,
    allow_origins=["http://localhost:3000", "http://localhost:5173"],
    allow_methods=["GET"],
    allow_headers=["Authorization", "Content-Type"],
    allow_credentials=True,
)


def es_png_valido(ruta: Path) -> bool:
    """Return whether a file is a decodable PNG image."""
    if ruta.suffix.lower() != ".png":
        return False

    try:
        carpeta = CARPETA_GRAFICAS.resolve(strict=True)
        archivo = ruta.resolve(strict=True)
        if archivo.parent != carpeta or not archivo.is_file():
            return False
        with Image.open(archivo) as imagen:
            imagen.verify()
            return imagen.format == "PNG"
    except (
        Image.DecompressionBombError,
        OSError,
        SyntaxError,
        UnidentifiedImageError,
        ValueError,
    ):
        return False


def catalogo_graficas() -> list[Grafica]:
    """Build the public chart catalogue from valid PNGs currently on disk."""
    if not CARPETA_GRAFICAS.is_dir():
        return []

    graficas = []
    for ruta in sorted(CARPETA_GRAFICAS.glob("*.png")):
        if es_png_valido(ruta):
            titulo = TITULOS_GRAFICAS.get(
                ruta.name,
                ruta.stem.replace("_", " ").capitalize(),
            )
            graficas.append(Grafica(title=titulo, image_url=f"/graficas/{ruta.name}"))
    return graficas


def catalogo_analitica() -> list[GraficaAnalitica]:
    """Return chart metadata without exposing server filesystem paths."""
    if not CARPETA_GRAFICAS.is_dir():
        return []

    graficas = []
    for ruta in sorted(CARPETA_GRAFICAS.glob("*.png")):
        if not es_png_valido(ruta):
            continue

        titulo = TITULOS_GRAFICAS.get(
            ruta.name,
            ruta.stem.replace("_", " ").capitalize(),
        )
        generated_at = datetime.fromtimestamp(
            ruta.stat().st_mtime,
            tz=timezone.utc,
        ).isoformat().replace("+00:00", "Z")
        graficas.append(
            GraficaAnalitica(
                id=ruta.stem,
                title=titulo,
                imageUrl=f"/api/analytics/charts/{ruta.stem}/image",
                altText=titulo,
                generatedAt=generated_at,
            )
        )
    return graficas


@app.get(
    "/api/analytics/charts",
    response_model=list[GraficaAnalitica],
)
def listar_graficas_analitica(
    _: None = Depends(verificar_token),
) -> list[GraficaAnalitica]:
    return catalogo_analitica()


@app.get("/api/analytics/charts/{chart_id}/image")
def obtener_imagen_analitica(
    chart_id: str,
    _: None = Depends(verificar_token),
) -> Response:
    if not chart_id or Path(chart_id).name != chart_id:
        raise HTTPException(status_code=404, detail="Gráfica no encontrada")

    ruta = CARPETA_GRAFICAS / f"{chart_id}.png"
    if not es_png_valido(ruta):
        raise HTTPException(status_code=404, detail="Gráfica no encontrada")

    return FileResponse(
        ruta,
        media_type="image/png",
        headers={"Cache-Control": "private, no-cache, must-revalidate"},
    )


@app.get("/api/graficas", response_model=list[Grafica])
def obtener_graficas(_: None = Depends(verificar_token)) -> list[Grafica]:
    return catalogo_graficas()


@app.get("/graficas/{filename}", include_in_schema=False)
def obtener_archivo_grafica(
    filename: str,
    _: None = Depends(verificar_token),
) -> Response:
    if Path(filename).name != filename or not filename.lower().endswith(".png"):
        raise HTTPException(status_code=404, detail="Gráfica no encontrada")

    ruta = CARPETA_GRAFICAS / filename
    if not es_png_valido(ruta):
        raise HTTPException(status_code=404, detail="Gráfica no encontrada")

    return FileResponse(
        ruta,
        media_type="image/png",
        headers={"Cache-Control": "private, no-cache, must-revalidate"},
    )
